	TransparentShape.prototype.paintBackground = function(c, x, y, w, h)
	{
		c.setFillColor(mxConstants.NONE);
		c.rect(x, y, w, h);
		c.fill();
	};

	TransparentShape.prototype.paintForeground = function(c, x, y, w, h) 	{ };

