	c.setShadow(false);
	
	c.setFillColor(mxUtils.getValue(this.style, 'buttonColor', '#e0e0e0'));
	c.roundrect(w * 0.05, h * 0.1, w * 0.9, h * 0.35, w * 0.025, h * 0.05);
