	var isShadow = parseFloat(mxUtils.getValue(this.state.style, 'shadow', '0'));
	var strokeColor2 = mxUtils.getValue(this.style, 'strokeColor2', '#292929');
	
	strokeWidth = Math.min(strokeWidth1, strokeWidth2);

