	c.setStrokeWidth(2 * strokeWidth);
	c.setStrokeColor(strokeColor2);
	c.setLineJoin('round');

	if (isShadow == 1)
	{
		c.setShadow(true);
	}
	
	c.begin();
	c.moveTo(0, h * 0.6651);
	c.lineTo(0, h * 0.3349);
	c.lineTo(w * 0.5, 0);
	c.lineTo(w, h * 0.3349);
	c.lineTo(w, h * 0.6651);
	c.lineTo(w * 0.5, h);
