	var flipH = mxUtils.getValue(this.state.style, 'flipH', '0');
	(flipH == '0') ? c.setAlpha(shading[0]) : c.setAlpha(shading[1]); 
	
	c.begin();
	c.moveTo(0, h * 0.2732);
	c.lineTo(w * 0.5, h * 0.6392);
	c.lineTo(w * 0.5, h);
	c.lineTo(0, h * 0.634);
	c.close();
	c.fill();

	(flipH == '0') ? c.setAlpha(shading[1]) : c.setAlpha(shading[0]); 
	c.begin();
	c.moveTo(w * 0.5, h * 0.6392);
	c.lineTo(w, h * 0.2732);
	c.lineTo(w, h * 0.6392);
	c.lineTo(w * 0.5, h);
	c.close();
	c.fill();
	
	c.restore();
	c.setShadow(false);
	c.setLineJoin('round');
	
	c.begin();
	c.moveTo(0, h * 0.2732);
	c.lineTo(w * 0.5, h * 0.6392);
	c.lineTo(w * 0.5, h);
	c.lineTo(0, h * 0.634);
	c.close();
	c.stroke();

	c.begin();
	c.moveTo(w * 0.5, h * 0.6392);
	c.lineTo(w, h * 0.2732);
	c.lineTo(w, h * 0.6392);
	c.lineTo(w * 0.5, h);
	c.close();
	c.stroke();
	
	var strokeColor = mxUtils.getValue(this.state.style, 'strokeColor', '#000000');
	c.setFillColor(strokeColor);
	c.begin();
	c.moveTo(w * 0.374, h * 0.4742);
