	c.arcTo(w * 0.0325, h * 0.0206, 0, 0, 1, w * 0.4797, h * 0.5485);
	c.close();
	c.fill();

	c.setStrokeWidth(2 * strokeWidth);
	c.setStrokeColor(strokeColor2);
	c.setLineJoin('round');

	c.begin();
	c.moveTo(0, h * 0.634);
	c.lineTo(0, h * 0.2732);
