	c.lineTo(w * 0.5203, h * 0.3407);
	c.lineTo(w * 0.3892, h * 0.3246);
	c.close();
	c.moveTo(w * 0.2932, h * 0.3246);
	c.lineTo(w * 0.3919, h * 0.4128);
	c.lineTo(w * 0.3334, h * 0.4647);
	c.lineTo(w * 0.2357, h * 0.38);
	c.close();
