//**********************************************************************************************************************************************************
//Outcome
//**********************************************************************************************************************************************************
/**
* Extends mxShape.
*/
function mxArchiMate3Outcome(bounds, fill, stroke, strokewidth)
{
	mxShape.call(this);
	this.bounds = bounds;
	this.fill = fill;
	this.stroke = stroke;
	this.strokewidth = (strokewidth != null) ? strokewidth : 1;
};

/**
* Extends mxShape.
*/
mxUtils.extend(mxArchiMate3Outcome, mxShape);

mxArchiMate3Outcome.prototype.cst = {
		OUTCOME : 'mxgraph.archimate3.outcome'
};

/**
* Function: paintVertexShape
* 
* Paints the vertex shape.
*/
mxArchiMate3Outcome.prototype.paintVertexShape = function(c, x, y, w, h)
{
	c.translate(x, y);
	this.background(c, 0, 0, w, h);
	c.setShadow(false);
};

mxArchiMate3Outcome.prototype.background = function(c, x, y, w, h)
{
		var sw = mxUtils.getValue(this.style, mxConstants.STYLE_STROKEWIDTH, 1);

		c.ellipse(0, w * 0.2, w * 0.8, h * 0.8);
		c.fillAndStroke();
		c.ellipse(w * 0.15, w * 0.35, w * 0.5, h * 0.5);
		c.stroke();
		c.ellipse(w * 0.3, w * 0.5, w * 0.2, h * 0.2);
		c.stroke();

		c.setStrokeWidth(3 * sw);
		c.setLineCap('round');		
		c.begin();
		c.moveTo(w * 0.4, h * 0.6);
		c.lineTo(w * 0.9, h * 0.1);
		c.moveTo(w * 0.42, h * 0.4);
		c.lineTo(w * 0.4, h * 0.6);
		c.lineTo(w * 0.6, h * 0.58);
		c.moveTo(w * 0.8, 0);
		c.lineTo(w * 0.75, h * 0.25);
		c.lineTo(w, h * 0.2);
		c.stroke();
};

mxCellRenderer.registerShape(mxArchiMate3Outcome.prototype.cst.OUTCOME, mxArchiMate3Outcome);

mxArchiMate3Outcome.prototype.getConstraints = function(style, w, h)
{
	var constr = [];
	// The target as painted: its top is at 0.2 of the width, which is ty of
	// the height. Relative points, so edges follow a resize that keeps the
	// proportions
	var ty = (h > 0) ? 0.2 * w / h : 0;
	var d = 0.4 * Math.SQRT1_2;

	// Top, sides, bottom and 45 degree points of the target, and the end of the arrow
	constr.push(new mxConnectionConstraint(new mxPoint(0.4, ty), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.9, 0.1), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.8, ty + 0.4), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.4 + d, ty + 0.4 + d), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.4, ty + 0.8), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.4 - d, ty + 0.4 + d), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0, ty + 0.4), false));
	constr.push(new mxConnectionConstraint(new mxPoint(0.4 - d, ty + 0.4 - d), false));

	return (constr);
};

