/**
* Extends mxShape.
*/
function mxArchiMate3Network(bounds, fill, stroke, strokewidth)
{
	mxShape.call(this);
	this.bounds = bounds;
	this.fill = fill;
	this.stroke = stroke;
	this.strokewidth = (strokewidth != null) ? strokewidth : 1;
};

/**
* Extends mxShape.
*/
mxUtils.extend(mxArchiMate3Network, mxShape);

mxArchiMate3Network.prototype.cst = {
		NETWORK : 'mxgraph.archimate3.network'
};

/**
* Function: paintVertexShape
* 
* Paints the vertex shape.
*/
mxArchiMate3Network.prototype.paintVertexShape = function(c, x, y, w, h)
{
	c.translate(x, y);
	this.background(c, 0, 0, w, h);
	c.setShadow(false);
};

mxArchiMate3Network.prototype.background = function(c, x, y, w, h)
{
		c.translate(0, 2);
		h = h - 4;
		
		c.begin();
		c.moveTo(w * 0.4, h * 0.2);
		c.lineTo(w * 0.85, h * 0.2);
		c.lineTo(w * 0.6, h * 0.8);
		c.lineTo(w * 0.15, h * 0.8);
		c.close();
		c.stroke();
		
		var strokeColor = mxUtils.getValue(this.style, mxConstants.STYLE_STROKECOLOR, '#000000');
		c.setFillColor(strokeColor);
		
		c.ellipse(w * 0.25, 0, w * 0.3, h * 0.4);
		c.fill();
		
		c.ellipse(w * 0.7, 0, w * 0.3, h * 0.4);
		c.fill();
		
		c.ellipse(0, h * 0.6, w * 0.3, h * 0.4);
		c.fill();
		
		c.ellipse(w * 0.45, h * 0.6, w * 0.3, h * 0.4);
		c.fill();
};

mxCellRenderer.registerShape(mxArchiMate3Network.prototype.cst.NETWORK, mxArchiMate3Network);

mxArchiMate3Network.prototype.getConstraints = function(style, w, h)
{
	var constr = [];

	// The outer sides of the four nodes, painted 2 units in from the top and bottom
	constr.push(new mxConnectionConstraint(new mxPoint(0.4, 0), false, null, 0, 2));
	constr.push(new mxConnectionConstraint(new mxPoint(0.85, 0), false, null, 0, 2));
	constr.push(new mxConnectionConstraint(new mxPoint(1, 0.2), false, null, 0, 1.2));
	constr.push(new mxConnectionConstraint(new mxPoint(0.75, 0.8), false, null, 0, -1.2));
	constr.push(new mxConnectionConstraint(new mxPoint(0.6, 1), false, null, 0, -2));
	constr.push(new mxConnectionConstraint(new mxPoint(0.15, 1), false, null, 0, -2));
	constr.push(new mxConnectionConstraint(new mxPoint(0, 0.8), false, null, 0, -1.2));
	constr.push(new mxConnectionConstraint(new mxPoint(0.25, 0.2), false, null, 0, 1.2));

	return (constr);
};

