//Stairs
//**********************************************************************************************************************************************************
/**
* Extends mxShape.
*/
function mxFloorplanStairs(bounds, fill, stroke, strokewidth)
{
	mxShape.call(this);
	this.bounds = bounds;
	this.fill = fill;
	this.stroke = stroke;
	this.strokewidth = (strokewidth != null) ? strokewidth : 1;
};

/**
* Extends mxShape.
*/
mxUtils.extend(mxFloorplanStairs, mxShape);

mxFloorplanStairs.prototype.cst = {
		STAIRS : 'mxgraph.floorplan.stairs'
};

/**
 * Variable: maxSteps
 *
 * Maximum number of steps. Default is 10000.
 */
mxFloorplanStairs.prototype.maxSteps = 10000;

/**
* Function: paintVertexShape
* 
* Paints the vertex shape.
*/
mxFloorplanStairs.prototype.paintVertexShape = function(c, x, y, w, h)
{
	c.translate(x, y);
	var minW = Math.max(w, 50);
	this.background(c, x, y, minW, h);
};

mxFloorplanStairs.prototype.background = function(c, x, y, w, h)
{
	c.rect(0, 0, w, h);
	c.fillAndStroke();
	
	var step = 25;
	c.setShadow(false);
	
	c.begin();
	
	for (var i = 25, n = 0; i < w && n < this.maxSteps; i = i + step, n++)
	{
		c.moveTo(i, 0);
		c.lineTo(i, h);
	}
	
	c.stroke();
	
	c.begin();
	c.moveTo(0, h * 0.5);
	c.lineTo(w, h * 0.5);
	c.moveTo(w - step, 0);
	c.lineTo(w, h * 0.5);
	c.lineTo(w - step, h);
	c.stroke();
};

mxCellRenderer.registerShape(mxFloorplanStairs.prototype.cst.STAIRS, mxFloorplanStairs);

