//Stairs
//**********************************************************************************************************************************************************
/**
* Extends mxShape.
*/
function mxFloorplanStairsRest(bounds, fill, stroke, strokewidth)
{
	mxShape.call(this);
	this.bounds = bounds;
	this.fill = fill;
	this.stroke = stroke;
	this.strokewidth = (strokewidth != null) ? strokewidth : 1;
};

/**
* Extends mxShape.
*/
mxUtils.extend(mxFloorplanStairsRest, mxShape);

mxFloorplanStairsRest.prototype.cst = {
		STAIRS : 'mxgraph.floorplan.stairsRest'
};

/**
 * Variable: maxSteps
 *
 * Maximum number of steps. Default is 10000.
 */
mxFloorplanStairsRest.prototype.maxSteps = 10000;

/**
* Function: paintVertexShape
* 
* Paints the vertex shape.
*/
mxFloorplanStairsRest.prototype.paintVertexShape = function(c, x, y, w, h)
{
	c.translate(x, y);
	var minW = Math.max(w, 50, h);
	var minH = Math.min(w, h);
	this.background(c, x, y, minW, h);
};

mxFloorplanStairsRest.prototype.background = function(c, x, y, w, h)
{
	c.rect(0, 0, w, h);
	c.fillAndStroke();
	
	var step = 25;
	c.setShadow(false);
	
	c.begin();
	
	for (var i = 25, n = 0; i < w - h * 0.5 && n < this.maxSteps; i = i + step, n++)
	{
		c.moveTo(i, 0);
		c.lineTo(i, h);
	}
	
	c.stroke();
	
	c.begin();
	c.moveTo(0, h * 0.5);
	c.lineTo(w, h * 0.5);
	
	c.moveTo(w, 0);
	c.lineTo(w - h * 0.5, h * 0.5);
	c.lineTo(w, h);
	
	c.moveTo(w - h * 0.5, 0);
	c.lineTo(w - h * 0.5, h);
	
	c.moveTo(0, h * 0.5);
	c.lineTo(w, h * 0.5);
	c.stroke();
};

mxCellRenderer.registerShape(mxFloorplanStairsRest.prototype.cst.STAIRS, mxFloorplanStairsRest);

