mxShapeSysMLControlOperator.prototype.foreground = function(c, x, y, w, h)
{
	var xSize = 130;
	var ySize = 20;
	
	xSize = Math.min(xSize, w);
	
	if (xSize > ySize)
	{
		c.begin();
		c.moveTo(0, ySize);
		c.lineTo(xSize - ySize * 0.5, ySize);
		c.lineTo(xSize, ySize * 0.5);
		c.lineTo(xSize, 0);
		c.stroke();
	}
};

