		MANUAL : 'man',
		DIAPHRAGM : 'diaph',
		BALANCED_DIAPHRAGM : 'balDiaph',
		MOTOR : 'motor',
		NONE : 'none',
		SPRING : 'spring',
		PILOT : 'pilot',
		POWERED: 'powered',
		SOLENOID : 'solenoid',
		SOLENOID_MANUAL_RESET : 'solenoidManRes',
		SINGLE_ACTING : 'singActing',
		DOUBLE_ACTING : 'dblActing',
		PILOT_CYLINDER : 'pilotCyl',
		DIGITAL : 'digital',
		WEIGHT : 'weight',
		KEY : 'key',
		ELECTRO_HYDRAULIC : 'elHyd',
		//types
		VALVE_TYPE : 'valveType',
		BUTTERFLY : 'butterfly',
		CHECK : 'check',
		GATE : 'gate',
		GLOBE : 'globe',
		NEEDLE : 'needle',
		PLUG : 'plug',
		SELF_DRAINING : 'selfDrain',
		ANGLE : 'angle',
